from collections import deque
from typing import List

def canAscend(wall: List[List[str]], w: int) -> int:
    n, m = len(wall), len(wall[0])
    cells = [(r, c) for r in range(n) for c in range(m) if wall[r][c] == 'x']
    w2 = w * w
    # 状态 (行, 列, 本行已做的水平跳跃次数)，所有底行的 'x' 同时作为起点
    dist = {}
    dq = deque()
    for c in range(m):
        if wall[n - 1][c] == 'x':
            dist[(n - 1, c, 0)] = 0
            dq.append((n - 1, c, 0))
    while dq:
        r, c, h = dq.popleft()
        d = dist[(r, c, h)]
        if r == 0:
            return d                      # BFS 第一次到顶行就是最少跳数
        for nr, nc in cells:
            if nr > r or (nr, nc) == (r, c):
                continue                  # 不能往下跳
            if (nr - r) ** 2 + (nc - c) ** 2 > w2:
                continue
            if nr == r:
                if h == 2:
                    continue              # 同一行最多水平跳 2 次
                st = (nr, nc, h + 1)
            else:
                st = (nr, nc, 0)          # 向上跳后水平计数清零
            if st not in dist:
                dist[st] = d + 1
                dq.append(st)
    return -1
